out={}; err=[]
for vid,s in src.items():
    p,n,q,ans,fin=D[vid]
    sp=[x['text'] for x in s['phrases']]
    if len(p)!=len(sp) or len(n)!=len(s['nouns']): err.append(vid)
    rec=[]
    for r in s['recall']:
        if r in sp: rec.append(p[sp.index(r)])
        elif r in s['nouns']: rec.append(n[s['nouns'].index(r)])
        else: rec.append(fin)
    out[vid]={"phrases":p,"nouns":n,"question":q,"answer":ans,"captions":{},"recall":rec}
print('err',err, len(out))
json.dump(out,open(R+'de/tr.json','w'),ensure_ascii=False,indent=1)
